CREATE TABLE group_reservation(id BIGINT AUTO_INCREMENT PRIMARY KEY,group_code VARCHAR(40) NOT NULL,group_name VARCHAR(150) NOT NULL,group_type VARCHAR(24) NOT NULL,status TINYINT NOT NULL DEFAULT 0,organizer_name VARCHAR(120),contact_phone VARCHAR(40),contact_email VARCHAR(160),ar_account_id BIGINT NULL,arrival_date DATE NOT NULL,departure_date DATE NOT NULL,currency CHAR(3) NOT NULL,booking_source VARCHAR(40) NOT NULL,billing_mode VARCHAR(24) NOT NULL DEFAULT 'INDIVIDUAL_PAY',notes VARCHAR(1000),created_by BIGINT NOT NULL,create_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),update_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uk_group_code(group_code),KEY idx_group_search(status,arrival_date,departure_date),FOREIGN KEY(ar_account_id) REFERENCES ar_account(id),FOREIGN KEY(created_by) REFERENCES sys_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE group_room_block(id BIGINT AUTO_INCREMENT PRIMARY KEY,group_id BIGINT NOT NULL,room_type_id BIGINT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,blocked_quantity INT NOT NULL,picked_up_quantity INT NOT NULL DEFAULT 0,released_quantity INT NOT NULL DEFAULT 0,rate_mode VARCHAR(24) NOT NULL,negotiated_rate DECIMAL(12,2),cut_off_date DATE,status TINYINT NOT NULL DEFAULT 0,create_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),update_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uk_group_block(group_id,room_type_id,start_date,end_date),KEY idx_group_block_inventory(room_type_id,status,start_date,end_date),FOREIGN KEY(group_id) REFERENCES group_reservation(id),FOREIGN KEY(room_type_id) REFERENCES room_type(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE group_rooming_entry(id BIGINT AUTO_INCREMENT PRIMARY KEY,group_id BIGINT NOT NULL,block_id BIGINT NOT NULL,guest_profile_id BIGINT NULL,booking_id BIGINT NULL,request_key VARCHAR(64) NOT NULL,status TINYINT NOT NULL DEFAULT 0,create_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),update_time DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),UNIQUE KEY uk_group_rooming_request(request_key),UNIQUE KEY uk_group_rooming_booking(booking_id),KEY idx_group_rooming(group_id,status,id),FOREIGN KEY(group_id) REFERENCES group_reservation(id),FOREIGN KEY(block_id) REFERENCES group_room_block(id),FOREIGN KEY(guest_profile_id) REFERENCES guest_profile(id),FOREIGN KEY(booking_id) REFERENCES booking(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE booking ADD COLUMN group_id BIGINT NULL AFTER reservation_policy_id,ADD COLUMN group_block_id BIGINT NULL AFTER group_id,ADD KEY idx_booking_group(group_id,status),ADD CONSTRAINT fk_booking_group FOREIGN KEY(group_id) REFERENCES group_reservation(id),ADD CONSTRAINT fk_booking_group_block FOREIGN KEY(group_block_id) REFERENCES group_room_block(id);
